-- =====================================================================
-- =====================================================
-- BillSprout/LifeSprout ERP - Functions and Triggers
-- =====================================================
-- This migration creates database functions and triggers for automation
-- Created: 2024
-- Description: Triggers for updated_at, stock management, and reporting functions

-- =====================================================
-- 1. UPDATED_AT TIMESTAMP TRIGGER FUNCTION
-- =====================================================
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Apply updated_at trigger to all relevant tables
DROP TRIGGER IF EXISTS set_updated_at_tenants ON tenants;
CREATE TRIGGER set_updated_at_tenants
    BEFORE UPDATE ON tenants
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

DROP TRIGGER IF EXISTS set_updated_at_branches ON branches;
CREATE TRIGGER set_updated_at_branches
    BEFORE UPDATE ON branches
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

DROP TRIGGER IF EXISTS set_updated_at_users ON users;
CREATE TRIGGER set_updated_at_users
    BEFORE UPDATE ON users
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

DROP TRIGGER IF EXISTS set_updated_at_suppliers ON suppliers;
CREATE TRIGGER set_updated_at_suppliers
    BEFORE UPDATE ON suppliers
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

DROP TRIGGER IF EXISTS set_updated_at_customers ON customers;
CREATE TRIGGER set_updated_at_customers
    BEFORE UPDATE ON customers
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

DROP TRIGGER IF EXISTS set_updated_at_products ON products;
CREATE TRIGGER set_updated_at_products
    BEFORE UPDATE ON products
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

DROP TRIGGER IF EXISTS set_updated_at_batches ON batches;
CREATE TRIGGER set_updated_at_batches
    BEFORE UPDATE ON batches
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

DROP TRIGGER IF EXISTS set_updated_at_sales ON sales;
CREATE TRIGGER set_updated_at_sales
    BEFORE UPDATE ON sales
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

DROP TRIGGER IF EXISTS set_updated_at_purchases ON purchases;
CREATE TRIGGER set_updated_at_purchases
    BEFORE UPDATE ON purchases
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

DROP TRIGGER IF EXISTS set_updated_at_stock_transfers ON stock_transfers;
CREATE TRIGGER set_updated_at_stock_transfers
    BEFORE UPDATE ON stock_transfers
    FOR EACH ROW
    EXECUTE FUNCTION update_updated_at_column();

-- =====================================================
-- 2. STOCK MANAGEMENT - SALE TRIGGERS
-- =====================================================
-- Function to update stock on sale item insert
CREATE OR REPLACE FUNCTION update_stock_on_sale()
RETURNS TRIGGER AS $$
BEGIN
    -- Decrease stock quantity in batches table
    UPDATE batches
    SET stock_quantity = stock_quantity - NEW.quantity
    WHERE id = NEW.batch_id;
    
    -- Check if stock went negative (should not happen with proper validation)
    IF (SELECT stock_quantity FROM batches WHERE id = NEW.batch_id) < 0 THEN
        RAISE EXCEPTION 'Insufficient stock for batch %', NEW.batch_id;
    END IF;
    
    -- Create stock movement record
    INSERT INTO stock_movements (
        tenant_id,
        product_id,
        batch_id,
        branch_id,
        movement_type,
        quantity,
        reference_id,
        notes,
        created_by
    )
    SELECT 
        s.tenant_id,
        NEW.product_id,
        NEW.batch_id,
        s.branch_id,
        'sale',
        -NEW.quantity,
        NEW.sale_id,
        'Sale invoice: ' || s.invoice_number,
        s.created_by
    FROM sales s
    WHERE s.id = NEW.sale_id;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_update_stock_on_sale ON sale_items;
CREATE TRIGGER trigger_update_stock_on_sale
    AFTER INSERT ON sale_items
    FOR EACH ROW
    EXECUTE FUNCTION update_stock_on_sale();

-- =====================================================
-- 3. STOCK MANAGEMENT - PURCHASE TRIGGERS
-- =====================================================
-- Function to update/create stock on purchase item insert
CREATE OR REPLACE FUNCTION update_stock_on_purchase()
RETURNS TRIGGER AS $$
DECLARE
    v_batch_id UUID;
    v_tenant_id UUID;
    v_branch_id UUID;
BEGIN
    -- Get tenant_id and branch_id from purchase
    SELECT tenant_id, branch_id INTO v_tenant_id, v_branch_id
    FROM purchases WHERE id = NEW.purchase_id;
    
    -- Check if batch already exists
    SELECT id INTO v_batch_id
    FROM batches
    WHERE product_id = NEW.product_id
      AND batch_number = NEW.batch_number
      AND branch_id = v_branch_id;
    
    IF v_batch_id IS NULL THEN
        -- Create new batch
        INSERT INTO batches (
            product_id,
            tenant_id,
            branch_id,
            batch_number,
            mfg_date,
            exp_date,
            purchase_price,
            ptr_price,
            mrp,
            selling_price,
            wholesale_price,
            stock_quantity,
            free_quantity,
            supplier_id
        )
        SELECT 
            NEW.product_id,
            v_tenant_id,
            v_branch_id,
            NEW.batch_number,
            NEW.mfg_date,
            NEW.exp_date,
            NEW.purchase_price,
            NEW.ptr_price,
            NEW.mrp,
            NEW.mrp, -- Default selling price = MRP
            NEW.ptr_price, -- Default wholesale price = PTR
            NEW.quantity + NEW.free_quantity,
            NEW.free_quantity,
            p.supplier_id
        FROM purchases p
        WHERE p.id = NEW.purchase_id
        RETURNING id INTO v_batch_id;
        
        -- Update purchase_items with the new batch_id
        UPDATE purchase_items SET batch_id = v_batch_id WHERE id = NEW.id;
    ELSE
        -- Update existing batch
        UPDATE batches
        SET 
            stock_quantity = stock_quantity + NEW.quantity + NEW.free_quantity,
            free_quantity = free_quantity + NEW.free_quantity,
            purchase_price = NEW.purchase_price,
            ptr_price = COALESCE(NEW.ptr_price, ptr_price),
            mrp = NEW.mrp,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = v_batch_id;
        
        -- Update purchase_items with the existing batch_id
        UPDATE purchase_items SET batch_id = v_batch_id WHERE id = NEW.id;
    END IF;
    
    -- Create stock movement record
    INSERT INTO stock_movements (
        tenant_id,
        product_id,
        batch_id,
        branch_id,
        movement_type,
        quantity,
        reference_id,
        notes,
        created_by
    )
    SELECT 
        p.tenant_id,
        NEW.product_id,
        v_batch_id,
        p.branch_id,
        'purchase',
        NEW.quantity + NEW.free_quantity,
        NEW.purchase_id,
        'Purchase invoice: ' || p.purchase_number,
        p.created_by
    FROM purchases p
    WHERE p.id = NEW.purchase_id;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_update_stock_on_purchase ON purchase_items;
CREATE TRIGGER trigger_update_stock_on_purchase
    AFTER INSERT ON purchase_items
    FOR EACH ROW
    EXECUTE FUNCTION update_stock_on_purchase();

-- =====================================================
-- 4. RESTRICTED DRUG LOG TRIGGER
-- =====================================================
-- Function to automatically log Schedule H/H1/Narcotic sales
CREATE OR REPLACE FUNCTION log_restricted_drug_sale()
RETURNS TRIGGER AS $$
DECLARE
    v_is_restricted BOOLEAN;
    v_product_name VARCHAR(500);
    v_sale_record RECORD;
BEGIN
    -- Check if product is restricted
    SELECT 
        (is_schedule_h OR is_schedule_h1 OR is_narcotic),
        name
    INTO v_is_restricted, v_product_name
    FROM products
    WHERE id = NEW.product_id;
    
    IF v_is_restricted THEN
        -- Get sale information
        SELECT * INTO v_sale_record FROM sales WHERE id = NEW.sale_id;
        
        -- Insert into restricted_drug_logs
        INSERT INTO restricted_drug_logs (
            tenant_id,
            sale_id,
            product_id,
            product_name,
            batch_number,
            quantity,
            customer_name,
            doctor_name,
            doctor_mci_no,
            pharmacist_id,
            prescription_id
        )
        VALUES (
            v_sale_record.tenant_id,
            NEW.sale_id,
            NEW.product_id,
            v_product_name,
            NEW.batch_number,
            NEW.quantity,
            v_sale_record.customer_name,
            v_sale_record.doctor_name,
            v_sale_record.doctor_mci_no,
            v_sale_record.pharmacist_authorized_by,
            v_sale_record.prescription_id
        );
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_log_restricted_drug_sale ON sale_items;
CREATE TRIGGER trigger_log_restricted_drug_sale
    AFTER INSERT ON sale_items
    FOR EACH ROW
    EXECUTE FUNCTION log_restricted_drug_sale();

-- =====================================================
-- 5. STOCK TRANSFER TRIGGERS
-- =====================================================
-- Function to handle stock transfer on status change
CREATE OR REPLACE FUNCTION handle_stock_transfer()
RETURNS TRIGGER AS $$
BEGIN
    -- When transfer is received, update stock
    IF NEW.status = 'received' AND OLD.status != 'received' THEN
        -- Decrease stock from source branch
        UPDATE batches
        SET stock_quantity = stock_quantity - NEW.quantity
        WHERE id = NEW.batch_id
          AND branch_id = NEW.from_branch_id;
        
        -- Check if we have enough stock
        IF (SELECT stock_quantity FROM batches WHERE id = NEW.batch_id AND branch_id = NEW.from_branch_id) < 0 THEN
            RAISE EXCEPTION 'Insufficient stock in source branch for transfer %', NEW.transfer_number;
        END IF;
        
        -- Create or update stock in destination branch
        DECLARE
            v_dest_batch_id UUID;
            v_batch_record RECORD;
        BEGIN
            -- Get batch details
            SELECT * INTO v_batch_record FROM batches WHERE id = NEW.batch_id;
            
            -- Check if batch exists in destination branch
            SELECT id INTO v_dest_batch_id
            FROM batches
            WHERE product_id = NEW.product_id
              AND batch_number = v_batch_record.batch_number
              AND branch_id = NEW.to_branch_id;
            
            IF v_dest_batch_id IS NULL THEN
                -- Create new batch in destination branch
                INSERT INTO batches (
                    product_id,
                    tenant_id,
                    branch_id,
                    batch_number,
                    mfg_date,
                    exp_date,
                    purchase_price,
                    ptr_price,
                    mrp,
                    selling_price,
                    wholesale_price,
                    stock_quantity,
                    supplier_id
                )
                VALUES (
                    v_batch_record.product_id,
                    v_batch_record.tenant_id,
                    NEW.to_branch_id,
                    v_batch_record.batch_number,
                    v_batch_record.mfg_date,
                    v_batch_record.exp_date,
                    v_batch_record.purchase_price,
                    v_batch_record.ptr_price,
                    v_batch_record.mrp,
                    v_batch_record.selling_price,
                    v_batch_record.wholesale_price,
                    NEW.quantity,
                    v_batch_record.supplier_id
                );
            ELSE
                -- Update existing batch
                UPDATE batches
                SET stock_quantity = stock_quantity + NEW.quantity
                WHERE id = v_dest_batch_id;
            END IF;
        END;
        
        -- Create stock movement records
        INSERT INTO stock_movements (
            tenant_id,
            product_id,
            batch_id,
            branch_id,
            movement_type,
            quantity,
            reference_id,
            notes,
            created_by
        )
        VALUES (
            NEW.tenant_id,
            NEW.product_id,
            NEW.batch_id,
            NEW.from_branch_id,
            'transfer_out',
            -NEW.quantity,
            NEW.id,
            'Transfer to branch: ' || NEW.transfer_number,
            NEW.initiated_by
        );
        
        INSERT INTO stock_movements (
            tenant_id,
            product_id,
            batch_id,
            branch_id,
            movement_type,
            quantity,
            reference_id,
            notes,
            created_by
        )
        VALUES (
            NEW.tenant_id,
            NEW.product_id,
            NEW.batch_id,
            NEW.to_branch_id,
            'transfer_in',
            NEW.quantity,
            NEW.id,
            'Transfer from branch: ' || NEW.transfer_number,
            NEW.received_by
        );
        
        -- Set received_at timestamp
        NEW.received_at = CURRENT_TIMESTAMP;
    END IF;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_handle_stock_transfer ON stock_transfers;
CREATE TRIGGER trigger_handle_stock_transfer
    BEFORE UPDATE ON stock_transfers
    FOR EACH ROW
    EXECUTE FUNCTION handle_stock_transfer();

-- =====================================================
-- 6. REPORTING FUNCTIONS
-- =====================================================

-- Function to get near-expiry items (expiring within N days)
CREATE OR REPLACE FUNCTION get_near_expiry_items(
    p_tenant_id UUID,
    p_branch_id UUID DEFAULT NULL,
    p_days_threshold INTEGER DEFAULT 90
)
RETURNS TABLE (
    batch_id UUID,
    product_id UUID,
    product_name VARCHAR,
    batch_number VARCHAR,
    exp_date DATE,
    days_to_expiry INTEGER,
    stock_quantity INTEGER,
    branch_name VARCHAR,
    value_at_cost DECIMAL
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        b.id as batch_id,
        p.id as product_id,
        p.name as product_name,
        b.batch_number,
        b.exp_date,
        (b.exp_date - CURRENT_DATE)::INTEGER as days_to_expiry,
        b.stock_quantity,
        br.branch_name,
        (b.stock_quantity * b.purchase_price) as value_at_cost
    FROM batches b
    JOIN products p ON b.product_id = p.id
    JOIN branches br ON b.branch_id = br.id
    WHERE b.tenant_id = p_tenant_id
      AND (p_branch_id IS NULL OR b.branch_id = p_branch_id)
      AND b.stock_quantity > 0
      AND b.exp_date <= CURRENT_DATE + p_days_threshold
      AND b.exp_date > CURRENT_DATE
    ORDER BY b.exp_date ASC, p.name;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to get low stock items
CREATE OR REPLACE FUNCTION get_low_stock_items(
    p_tenant_id UUID,
    p_branch_id UUID DEFAULT NULL
)
RETURNS TABLE (
    product_id UUID,
    product_name VARCHAR,
    category VARCHAR,
    reorder_level INTEGER,
    current_stock BIGINT,
    branch_name VARCHAR
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        p.id as product_id,
        p.name as product_name,
        p.category,
        p.reorder_level,
        COALESCE(SUM(b.stock_quantity), 0) as current_stock,
        br.branch_name
    FROM products p
    JOIN branches br ON br.tenant_id = p.tenant_id
    LEFT JOIN batches b ON b.product_id = p.id AND b.branch_id = br.id
    WHERE p.tenant_id = p_tenant_id
      AND (p_branch_id IS NULL OR br.id = p_branch_id)
    GROUP BY p.id, p.name, p.category, p.reorder_level, br.branch_name
    HAVING COALESCE(SUM(b.stock_quantity), 0) <= p.reorder_level
    ORDER BY current_stock ASC, p.name;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to get expired items
CREATE OR REPLACE FUNCTION get_expired_items(
    p_tenant_id UUID,
    p_branch_id UUID DEFAULT NULL
)
RETURNS TABLE (
    batch_id UUID,
    product_id UUID,
    product_name VARCHAR,
    batch_number VARCHAR,
    exp_date DATE,
    days_expired INTEGER,
    stock_quantity INTEGER,
    branch_name VARCHAR,
    value_at_cost DECIMAL
) AS $$
BEGIN
    RETURN QUERY
    SELECT 
        b.id as batch_id,
        p.id as product_id,
        p.name as product_name,
        b.batch_number,
        b.exp_date,
        (CURRENT_DATE - b.exp_date)::INTEGER as days_expired,
        b.stock_quantity,
        br.branch_name,
        (b.stock_quantity * b.purchase_price) as value_at_cost
    FROM batches b
    JOIN products p ON b.product_id = p.id
    JOIN branches br ON b.branch_id = br.id
    WHERE b.tenant_id = p_tenant_id
      AND (p_branch_id IS NULL OR b.branch_id = p_branch_id)
      AND b.stock_quantity > 0
      AND b.exp_date < CURRENT_DATE
    ORDER BY b.exp_date DESC, p.name;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to get sales summary for date range
CREATE OR REPLACE FUNCTION get_sales_summary(
    p_tenant_id UUID,
    p_branch_id UUID DEFAULT NULL,
    p_start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,
    p_end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL
)
RETURNS TABLE (
    total_sales BIGINT,
    total_amount DECIMAL,
    total_gst DECIMAL,
    cash_sales DECIMAL,
    card_sales DECIMAL,
    upi_sales DECIMAL,
    credit_sales DECIMAL,
    pending_amount DECIMAL
) AS $$
BEGIN
    -- Default to current month if dates not provided
    p_start_date := COALESCE(p_start_date, date_trunc('month', CURRENT_DATE));
    p_end_date := COALESCE(p_end_date, CURRENT_TIMESTAMP);
    
    RETURN QUERY
    SELECT 
        COUNT(*)::BIGINT as total_sales,
        COALESCE(SUM(grand_total), 0) as total_amount,
        COALESCE(SUM(total_gst), 0) as total_gst,
        COALESCE(SUM(CASE WHEN payment_mode = 'cash' THEN grand_total ELSE 0 END), 0) as cash_sales,
        COALESCE(SUM(CASE WHEN payment_mode = 'card' THEN grand_total ELSE 0 END), 0) as card_sales,
        COALESCE(SUM(CASE WHEN payment_mode = 'upi' THEN grand_total ELSE 0 END), 0) as upi_sales,
        COALESCE(SUM(CASE WHEN payment_mode = 'credit' THEN grand_total ELSE 0 END), 0) as credit_sales,
        COALESCE(SUM(CASE WHEN payment_status IN ('pending', 'partial') THEN grand_total ELSE 0 END), 0) as pending_amount
    FROM sales
    WHERE tenant_id = p_tenant_id
      AND (p_branch_id IS NULL OR branch_id = p_branch_id)
      AND invoice_date >= p_start_date
      AND invoice_date <= p_end_date;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to get top selling products
CREATE OR REPLACE FUNCTION get_top_selling_products(
    p_tenant_id UUID,
    p_branch_id UUID DEFAULT NULL,
    p_start_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,
    p_end_date TIMESTAMP WITH TIME ZONE DEFAULT NULL,
    p_limit INTEGER DEFAULT 10
)
RETURNS TABLE (
    product_id UUID,
    product_name VARCHAR,
    category VARCHAR,
    total_quantity BIGINT,
    total_sales DECIMAL,
    sale_count BIGINT
) AS $$
BEGIN
    -- Default to current month if dates not provided
    p_start_date := COALESCE(p_start_date, date_trunc('month', CURRENT_DATE));
    p_end_date := COALESCE(p_end_date, CURRENT_TIMESTAMP);
    
    RETURN QUERY
    SELECT 
        p.id as product_id,
        p.name as product_name,
        p.category,
        SUM(si.quantity)::BIGINT as total_quantity,
        SUM(si.line_total) as total_sales,
        COUNT(DISTINCT si.sale_id)::BIGINT as sale_count
    FROM sale_items si
    JOIN products p ON si.product_id = p.id
    JOIN sales s ON si.sale_id = s.id
    WHERE s.tenant_id = p_tenant_id
      AND (p_branch_id IS NULL OR s.branch_id = p_branch_id)
      AND s.invoice_date >= p_start_date
      AND s.invoice_date <= p_end_date
    GROUP BY p.id, p.name, p.category
    ORDER BY total_sales DESC
    LIMIT p_limit;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- =====================================================
-- COMMENTS
-- =====================================================
COMMENT ON FUNCTION update_updated_at_column() IS 'Automatically updates the updated_at timestamp on row updates';
COMMENT ON FUNCTION update_stock_on_sale() IS 'Decreases stock and creates stock movement record when sale is made';
COMMENT ON FUNCTION update_stock_on_purchase() IS 'Increases stock and creates stock movement record when purchase is made';
COMMENT ON FUNCTION log_restricted_drug_sale() IS 'Automatically logs sales of Schedule H/H1/Narcotic drugs for compliance';
COMMENT ON FUNCTION handle_stock_transfer() IS 'Handles stock movement between branches when transfer is received';
COMMENT ON FUNCTION get_near_expiry_items(UUID, UUID, INTEGER) IS 'Returns items expiring within specified days threshold';
COMMENT ON FUNCTION get_low_stock_items(UUID, UUID) IS 'Returns items with stock below reorder level';
COMMENT ON FUNCTION get_expired_items(UUID, UUID) IS 'Returns expired items still in stock';
COMMENT ON FUNCTION get_sales_summary(UUID, UUID, TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE) IS 'Returns sales summary for given date range';
COMMENT ON FUNCTION get_top_selling_products(UUID, UUID, TIMESTAMP WITH TIME ZONE, TIMESTAMP WITH TIME ZONE, INTEGER) IS 'Returns top selling products by revenue';
-- =====================================================================
-- END 004_functions_triggers.sql
-- =====================================================================


-- =====================================================================
-- BEGIN 005_add_tenant_id_to_line_items.sql
-- =====================================================================
-- =====================================================
-- Migration: Add tenant_id to Line Item Tables
-- =====================================================
-- Created: 2025-01-24
-- Task: 1.1 Multi-Tenant RLS Implementation
-- Purpose: Add tenant_id column with NOT NULL constraint to sale_items and purchase_items
--          to enable direct RLS policy filtering

-- =====================================================
-- 1. Add tenant_id to sale_items
-- =====================================================

-- Step 1: Add column as nullable first (guarded so the file can be re-applied)
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema = 'public' AND table_name = 'sale_items'
                     AND column_name = 'tenant_id') THEN
        ALTER TABLE sale_items
        ADD COLUMN tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE;
    END IF;
END $$;

-- Step 2: Backfill existing data from parent sales table
UPDATE sale_items si
SET tenant_id = s.tenant_id
FROM sales s
WHERE si.sale_id = s.id
  AND si.tenant_id IS DISTINCT FROM s.tenant_id;

-- Step 3: Make column NOT NULL after backfill.
-- Only when every row is populated; otherwise the ALTER aborts the migration.
DO $$
DECLARE
    null_rows INTEGER;
BEGIN
    SELECT COUNT(*) INTO null_rows FROM sale_items WHERE tenant_id IS NULL;
    IF null_rows = 0 THEN
        ALTER TABLE sale_items ALTER COLUMN tenant_id SET NOT NULL;
    ELSE
        RAISE NOTICE 'sale_items.tenant_id left nullable: % orphan row(s)', null_rows;
    END IF;
END $$;

-- Step 4: Add index for RLS performance
CREATE INDEX IF NOT EXISTS idx_sale_items_tenant_id ON sale_items(tenant_id);

-- Add comment
COMMENT ON COLUMN sale_items.tenant_id IS 'Tenant identifier for multi-tenant RLS filtering';

-- =====================================================
-- 2. Add tenant_id to purchase_items
-- =====================================================

-- Step 1: Add column as nullable first (guarded so the file can be re-applied)
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema = 'public' AND table_name = 'purchase_items'
                     AND column_name = 'tenant_id') THEN
        ALTER TABLE purchase_items
        ADD COLUMN tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE;
    END IF;
END $$;

-- Step 2: Backfill existing data from parent purchases table
UPDATE purchase_items pi
SET tenant_id = p.tenant_id
FROM purchases p
WHERE pi.purchase_id = p.id
  AND pi.tenant_id IS DISTINCT FROM p.tenant_id;

-- Step 3: Make column NOT NULL after backfill
DO $$
DECLARE
    null_rows INTEGER;
BEGIN
    SELECT COUNT(*) INTO null_rows FROM purchase_items WHERE tenant_id IS NULL;
    IF null_rows = 0 THEN
        ALTER TABLE purchase_items ALTER COLUMN tenant_id SET NOT NULL;
    ELSE
        RAISE NOTICE 'purchase_items.tenant_id left nullable: % orphan row(s)', null_rows;
    END IF;
END $$;

-- Step 4: Add index for RLS performance
CREATE INDEX IF NOT EXISTS idx_purchase_items_tenant_id ON purchase_items(tenant_id);

-- Add comment
COMMENT ON COLUMN purchase_items.tenant_id IS 'Tenant identifier for multi-tenant RLS filtering';

-- =====================================================
-- 3. Fix users table tenant_id constraint
-- =====================================================

-- Add CHECK constraint allowing NULL only for super_admin role
-- This allows super_admin users to access all tenants
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conrelid = 'public.users'::regclass
                     AND conname = 'users_tenant_id_required') THEN
        ALTER TABLE users
        ADD CONSTRAINT users_tenant_id_required
        CHECK (tenant_id IS NOT NULL OR role = 'super_admin');
    END IF;
END $$;

-- Add comment explaining the constraint
COMMENT ON CONSTRAINT users_tenant_id_required ON users IS 
'Ensures all users except super_admin have a tenant_id assigned';

-- =====================================================
-- Verification Queries
-- =====================================================

-- Verify sale_items tenant_id population
DO $$
DECLARE
    null_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO null_count FROM sale_items WHERE tenant_id IS NULL;
    IF null_count > 0 THEN
        -- Reported, not fatal: an orphan line item (no parent sale) must not
        -- block the whole migration chain from applying.
        RAISE WARNING 'Found % sale_items with NULL tenant_id (orphaned line items)', null_count;
    ELSE
        RAISE NOTICE 'sale_items tenant_id backfill successful: all rows populated';
    END IF;
END $$;

-- Verify purchase_items tenant_id population
DO $$
DECLARE
    null_count INTEGER;
BEGIN
    SELECT COUNT(*) INTO null_count FROM purchase_items WHERE tenant_id IS NULL;
    IF null_count > 0 THEN
        RAISE WARNING 'Found % purchase_items with NULL tenant_id (orphaned line items)', null_count;
    ELSE
        RAISE NOTICE 'purchase_items tenant_id backfill successful: all rows populated';
    END IF;
END $$;

-- =====================================================
-- Summary
-- =====================================================
/*
This migration adds tenant_id to line item tables for direct RLS filtering:

Tables Modified:
1. sale_items - Added tenant_id UUID NOT NULL with foreign key and index
2. purchase_items - Added tenant_id UUID NOT NULL with foreign key and index
3. users - Added CHECK constraint for tenant_id requirement

Benefits:
- Direct RLS policy filtering without JOIN operations
- Improved query performance for line item queries
- Simplified RLS policy definitions
- Consistent tenant_id presence across all business tables

Next Steps:
- Task 1.2: Create RLS policies for all tables
- Task 1.3: Implement session variable setter
*/
-- =====================================================================
-- END 005_add_tenant_id_to_line_items.sql
-- =====================================================================


-- =====================================================================
-- BEGIN 006_update_line_items_rls_policies.sql
-- =====================================================================
-- =====================================================
-- Migration: Update RLS Policies for Line Item Tables
-- =====================================================
-- Created: 2025-01-24
-- Task: 1.1 Multi-Tenant RLS Implementation
-- Purpose: Update RLS policies for sale_items and purchase_items to use direct tenant_id filtering
--          instead of JOIN-based filtering for better performance
-- Dependencies: Requires 005_add_tenant_id_to_line_items.sql to be executed first

-- =====================================================
-- 1. Update SALE_ITEMS RLS Policies
-- =====================================================

-- Drop existing policies
DROP POLICY IF EXISTS "Users can access sale items from their tenant's sales" ON sale_items;
DROP POLICY IF EXISTS "Users can insert sale items for their tenant's sales" ON sale_items;

-- Create new policies using direct tenant_id filtering
DROP POLICY IF EXISTS "Users can access their tenant's sale items" ON sale_items;
CREATE POLICY "Users can access their tenant's sale items"
ON sale_items FOR ALL
USING (user_has_tenant_access(tenant_id));

DROP POLICY IF EXISTS "Users can insert sale items for their tenant" ON sale_items;
CREATE POLICY "Users can insert sale items for their tenant"
ON sale_items FOR INSERT
WITH CHECK (user_has_tenant_access(tenant_id));

-- Add comment explaining the improvement
COMMENT ON TABLE sale_items IS 'Line items for each sale - now includes tenant_id for direct RLS filtering';

-- =====================================================
-- 2. Update PURCHASE_ITEMS RLS Policies
-- =====================================================

-- Drop existing policies
DROP POLICY IF EXISTS "Users can access purchase items from their tenant's purchases" ON purchase_items;
DROP POLICY IF EXISTS "Users can insert purchase items for their tenant's purchases" ON purchase_items;

-- Create new policies using direct tenant_id filtering
DROP POLICY IF EXISTS "Users can access their tenant's purchase items" ON purchase_items;
CREATE POLICY "Users can access their tenant's purchase items"
ON purchase_items FOR ALL
USING (user_has_tenant_access(tenant_id));

DROP POLICY IF EXISTS "Users can insert purchase items for their tenant" ON purchase_items;
CREATE POLICY "Users can insert purchase items for their tenant"
ON purchase_items FOR INSERT
WITH CHECK (user_has_tenant_access(tenant_id));

-- Add comment explaining the improvement
COMMENT ON TABLE purchase_items IS 'Line items for each purchase - now includes tenant_id for direct RLS filtering';

-- =====================================================
-- Performance Verification Query
-- =====================================================

-- This query can be used to verify that indexes are being used
DO $$
BEGIN
    RAISE NOTICE 'RLS policy update completed successfully';
    RAISE NOTICE 'sale_items and purchase_items now use direct tenant_id filtering';
    RAISE NOTICE 'Query performance should be significantly improved';
    RAISE NOTICE 'Run EXPLAIN ANALYZE on queries to verify index usage';
END $$;

-- =====================================================
-- Summary
-- =====================================================
/*
Performance Improvements:
- BEFORE: RLS policies used EXISTS subquery with JOIN to parent table
  Example: EXISTS (SELECT 1 FROM sales WHERE sales.id = sale_items.sale_id AND ...)
  
- AFTER: RLS policies use direct tenant_id column filtering
  Example: user_has_tenant_access(tenant_id)

Benefits:
1. Eliminates JOIN operations in RLS checks
2. Utilizes indexes on tenant_id columns (created in migration 005)
3. Reduces query execution time for line item queries
4. Simplifies query plans
5. Consistent filtering pattern across all tables

Usage:
These policies work seamlessly with existing application code.
No application changes required after this migration.
*/
-- =====================================================================
-- END 006_update_line_items_rls_policies.sql
-- =====================================================================


-- =====================================================================
-- BEGIN 007_enhance_multi_tenant_features.sql
-- =====================================================================
-- =====================================================
-- Enhancement Migration: Multi-Tenant Features & Fixes
-- =====================================================
-- Created: 2025-01-08
-- Description: Completes multi-tenant isolation, pharmacist management,
--              pricing plans, public demo requests, and reporting views.
--
-- IDEMPOTENCY CONTRACT
-- This migration is safe to run repeatedly against a live database:
--   * tables/indexes use IF NOT EXISTS
--   * columns are added inside guarded DO blocks
--   * every CREATE POLICY is preceded by DROP POLICY IF EXISTS
--   * views are dropped and recreated
--   * seed data uses ON CONFLICT DO NOTHING
-- =====================================================

CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- =====================================================
-- 1. HELPER FUNCTIONS
-- =====================================================

-- Sets the tenant context for the current session (used by trusted server-side
-- callers). Client sessions via PostgREST do not set this, which is why
-- tenant_access_allowed() falls back to the users table.
CREATE OR REPLACE FUNCTION set_tenant_context(tenant_uuid UUID)
RETURNS void AS $$
BEGIN
    PERFORM set_config('app.current_tenant_id', tenant_uuid::TEXT, false);
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Returns the tenant id for the current request.
-- The authenticated user row is authoritative; the session setting is only a
-- fallback for trusted server-side callers with no auth.uid(). Deliberately in
-- that order so a client cannot widen its own scope by setting the variable.
CREATE OR REPLACE FUNCTION current_tenant_context()
RETURNS UUID AS $$
DECLARE
    user_tenant UUID;
    session_tenant TEXT;
BEGIN
    IF auth.uid() IS NOT NULL THEN
        SELECT tenant_id INTO user_tenant FROM users WHERE id = auth.uid();
        IF user_tenant IS NOT NULL THEN
            RETURN user_tenant;
        END IF;
    END IF;

    session_tenant := NULLIF(current_setting('app.current_tenant_id', true), '');
    IF session_tenant IS NULL THEN
        session_tenant := NULLIF(current_setting('app.tenant_id', true), '');
    END IF;

    IF session_tenant IS NOT NULL THEN
        RETURN session_tenant::UUID;
    END IF;

    RETURN NULL;
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION is_super_admin()
RETURNS BOOLEAN AS $$
BEGIN
    RETURN COALESCE(
        (SELECT role = 'super_admin' FROM users WHERE id = auth.uid()),
        false
    );
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

-- Single predicate used by every tenant-scoped policy below.
-- Super admins pass for any tenant; everyone else only for their own tenant.
-- A NULL check_tenant_id never passes.
CREATE OR REPLACE FUNCTION tenant_access_allowed(check_tenant_id UUID)
RETURNS BOOLEAN AS $$
BEGIN
    IF check_tenant_id IS NULL THEN
        RETURN false;
    END IF;

    IF is_super_admin() THEN
        RETURN true;
    END IF;

    RETURN check_tenant_id = current_tenant_context();
END;
$$ LANGUAGE plpgsql STABLE SECURITY DEFINER;

CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- =====================================================
-- 2. COLUMN ADDITIONS ON EXISTING TABLES
-- =====================================================

-- sales.billing_type (retail vs wholesale) - Requirement 2.4
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema = 'public'
                     AND table_name = 'sales'
                     AND column_name = 'billing_type') THEN
        ALTER TABLE sales ADD COLUMN billing_type VARCHAR(20) DEFAULT 'retail';
    END IF;

    -- Separate guard: the column may predate the constraint (001 inlines an
    -- anonymous check, older hand-patched databases may have neither).
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conrelid = 'public.sales'::regclass
                     AND pg_get_constraintdef(oid) ILIKE '%billing_type%') THEN
        ALTER TABLE sales ADD CONSTRAINT sales_billing_type_check
            CHECK (billing_type IN ('retail', 'wholesale'));
    END IF;
END $$;

-- sales.customer_gstin for wholesale billing - Requirement 2.4
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema = 'public'
                     AND table_name = 'sales'
                     AND column_name = 'customer_gstin') THEN
        ALTER TABLE sales ADD COLUMN customer_gstin VARCHAR(15);
    END IF;
END $$;

-- sale_items.tenant_id so line items can be filtered without a join.
-- Normally added by migration 005; guarded here so 007 is self-sufficient.
DO $$
DECLARE
    null_rows INTEGER;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema = 'public'
                     AND table_name = 'sale_items'
                     AND column_name = 'tenant_id') THEN
        ALTER TABLE sale_items
            ADD COLUMN tenant_id UUID REFERENCES tenants(id) ON DELETE CASCADE;

        UPDATE sale_items si
        SET tenant_id = s.tenant_id
        FROM sales s
        WHERE si.sale_id = s.id;

        SELECT COUNT(*) INTO null_rows FROM sale_items WHERE tenant_id IS NULL;
        IF null_rows = 0 THEN
            ALTER TABLE sale_items ALTER COLUMN tenant_id SET NOT NULL;
        ELSE
            RAISE NOTICE 'sale_items.tenant_id left nullable: % orphan rows', null_rows;
        END IF;
    END IF;
END $$;

-- demo_requests columns required by DemoRequestModel - Requirement 8.1
DO $$
DECLARE
    col RECORD;
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables
               WHERE table_schema = 'public' AND table_name = 'demo_requests') THEN
        FOR col IN
            SELECT * FROM (VALUES
                ('business_name', 'VARCHAR(255)'),
                ('email',         'VARCHAR(255)'),
                ('city',          'VARCHAR(100)'),
                ('pincode',       'VARCHAR(10)'),
                ('business_type', 'VARCHAR(100)'),
                ('num_branches',  'INTEGER DEFAULT 1'),
                ('message',       'TEXT')
            ) AS v(name, definition)
        LOOP
            IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                           WHERE table_schema = 'public'
                             AND table_name = 'demo_requests'
                             AND column_name = col.name) THEN
                EXECUTE format('ALTER TABLE demo_requests ADD COLUMN %I %s',
                               col.name, col.definition);
            END IF;
        END LOOP;
    END IF;
END $$;

-- =====================================================
-- 3. TABLES
-- =====================================================

-- 3a. Public lead capture - Requirement 8.1
CREATE TABLE IF NOT EXISTS demo_requests (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    name VARCHAR(255) NOT NULL,
    business_name VARCHAR(255),
    mobile VARCHAR(20) NOT NULL,
    email VARCHAR(255),
    city VARCHAR(100),
    pincode VARCHAR(10),
    business_type VARCHAR(100),
    num_branches INTEGER DEFAULT 1,
    message TEXT,
    status VARCHAR(50) DEFAULT 'new' CHECK (status IN ('new', 'contacted', 'converted', 'closed')),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 3b. Public pricing - Requirement 8.3
CREATE TABLE IF NOT EXISTS pricing_plans (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    plan_name VARCHAR(100) NOT NULL UNIQUE,
    plan_code VARCHAR(50) NOT NULL UNIQUE,
    price DECIMAL(15, 2) NOT NULL,
    gst_applicable BOOLEAN DEFAULT true,
    gst_percent DECIMAL(5, 2) DEFAULT 18.00,
    max_users INTEGER,
    max_branches INTEGER,
    max_products INTEGER,
    features JSONB,
    is_active BOOLEAN DEFAULT true,
    display_order INTEGER DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 3c. Pharmacists, tenant scoped, PIN stored only as a salted hash
--     - Requirements 7.1, 7.2
CREATE TABLE IF NOT EXISTS pharmacists (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    user_id UUID REFERENCES users(id) ON DELETE SET NULL,
    name VARCHAR(255) NOT NULL,
    email VARCHAR(255),
    phone VARCHAR(20),
    license_no VARCHAR(50),
    registration_no VARCHAR(100),
    pin_hash VARCHAR(255),
    pin_salt VARCHAR(64),
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (tenant_id, registration_no)
);

-- Guarded column adds for databases where an earlier pharmacists table exists
DO $$
DECLARE
    col RECORD;
BEGIN
    FOR col IN
        SELECT * FROM (VALUES
            ('user_id',         'UUID REFERENCES users(id) ON DELETE SET NULL'),
            ('email',           'VARCHAR(255)'),
            ('phone',           'VARCHAR(20)'),
            ('license_no',      'VARCHAR(50)'),
            ('registration_no', 'VARCHAR(100)'),
            ('pin_hash',        'VARCHAR(255)'),
            ('pin_salt',        'VARCHAR(64)'),
            ('is_active',       'BOOLEAN DEFAULT true'),
            ('updated_at',      'TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP')
        ) AS v(name, definition)
    LOOP
        IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                       WHERE table_schema = 'public'
                         AND table_name = 'pharmacists'
                         AND column_name = col.name) THEN
            EXECUTE format('ALTER TABLE pharmacists ADD COLUMN %I %s',
                           col.name, col.definition);
        END IF;
    END LOOP;
END $$;

-- =====================================================
-- 4. SEED DATA
-- =====================================================
INSERT INTO pricing_plans (plan_name, plan_code, price, max_users, max_branches, max_products, features, display_order) VALUES
('Gold Edition', 'gold', 26000.00, -1, -1, -1, '["Unlimited Users", "Unlimited Branches", "Unlimited Products", "Multi-Tenant Support", "Wholesale & Retail", "GST Compliance", "Schedule H Register", "OTA Updates", "24/7 Support"]', 1),
('Basic Plan', 'basic', 15000.00, 5, 1, 1000, '["5 Users", "1 Branch", "1000 Products", "Retail Billing", "GST Reports", "Email Support"]', 2),
('Professional Plan', 'professional', 35000.00, 20, 5, 5000, '["20 Users", "5 Branches", "5000 Products", "Retail & Wholesale", "Multi-Branch", "Advanced Reports", "Priority Support"]', 3)
ON CONFLICT (plan_code) DO NOTHING;

-- =====================================================
-- 5. ROW LEVEL SECURITY
-- =====================================================
-- Requirements 2.1, 2.2, 2.3: every tenant-scoped table below is gated on
-- tenant_access_allowed(tenant_id), which resolves the caller's tenant from the
-- users table (or a session override) and always passes for super admins.

ALTER TABLE products      ENABLE ROW LEVEL SECURITY;
ALTER TABLE batches       ENABLE ROW LEVEL SECURITY;
ALTER TABLE sales         ENABLE ROW LEVEL SECURITY;
ALTER TABLE sale_items    ENABLE ROW LEVEL SECURITY;
ALTER TABLE customers     ENABLE ROW LEVEL SECURITY;
ALTER TABLE suppliers     ENABLE ROW LEVEL SECURITY;
ALTER TABLE branches      ENABLE ROW LEVEL SECURITY;
ALTER TABLE pharmacists   ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenants       ENABLE ROW LEVEL SECURITY;
ALTER TABLE demo_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE pricing_plans ENABLE ROW LEVEL SECURITY;

-- 5a. Tenant-scoped tables
DO $$
DECLARE
    t TEXT;
BEGIN
    FOREACH t IN ARRAY ARRAY[
        'products', 'batches', 'sales', 'sale_items',
        'customers', 'suppliers', 'branches', 'pharmacists'
    ]
    LOOP
        EXECUTE format(
            'DROP POLICY IF EXISTS "Tenant isolation on %1$s" ON %1$I;
             CREATE POLICY "Tenant isolation on %1$s"
             ON %1$I FOR ALL
             USING (tenant_access_allowed(tenant_id))
             WITH CHECK (tenant_access_allowed(tenant_id));', t);
    END LOOP;
END $$;

-- Retire the earlier session-variable-only policies from previous revisions of
-- this migration; they never matched because PostgREST sessions do not set
-- app.current_tenant_id.
DROP POLICY IF EXISTS "Tenants can only access their own products" ON products;
DROP POLICY IF EXISTS "Tenants can only access their own batches" ON batches;
DROP POLICY IF EXISTS "Tenants can only access their own sales" ON sales;
DROP POLICY IF EXISTS "Tenants can only access their own customers" ON customers;
DROP POLICY IF EXISTS "Tenants can only access their own suppliers" ON suppliers;
DROP POLICY IF EXISTS "Tenants can only access their own branches" ON branches;

-- Consolidate the overlapping policies created by 002/006 on these same tables.
-- Policies are OR'd, so leaving two predicates in place makes the effective rule
-- hard to reason about. The single "Tenant isolation on <table>" policy above is
-- equivalent and is now the only one.
DROP POLICY IF EXISTS "Users can access their tenant's products" ON products;
DROP POLICY IF EXISTS "Users can insert products for their tenant" ON products;
DROP POLICY IF EXISTS "Users can access their tenant's batches" ON batches;
DROP POLICY IF EXISTS "Users can insert batches for their tenant" ON batches;
DROP POLICY IF EXISTS "Users can access their tenant's sales" ON sales;
DROP POLICY IF EXISTS "Users can insert sales for their tenant" ON sales;
DROP POLICY IF EXISTS "Users can access sale items from their tenant's sales" ON sale_items;
DROP POLICY IF EXISTS "Users can insert sale items for their tenant's sales" ON sale_items;
DROP POLICY IF EXISTS "Users can access their tenant's sale items" ON sale_items;
DROP POLICY IF EXISTS "Users can insert sale items for their tenant" ON sale_items;
DROP POLICY IF EXISTS "Users can access their tenant's customers" ON customers;
DROP POLICY IF EXISTS "Users can insert customers for their tenant" ON customers;
DROP POLICY IF EXISTS "Users can access their tenant's suppliers" ON suppliers;
DROP POLICY IF EXISTS "Users can insert suppliers for their tenant" ON suppliers;
DROP POLICY IF EXISTS "Users can access their tenant's branches" ON branches;
DROP POLICY IF EXISTS "Users can insert branches for their tenant" ON branches;

-- 5b. Tenants table: super admin full access, tenant members read/update own row
-- Superseded by the three policies below (002 created narrower duplicates).
DROP POLICY IF EXISTS "Super admins can view all tenants" ON tenants;
DROP POLICY IF EXISTS "Super admins can insert tenants" ON tenants;
DROP POLICY IF EXISTS "Users can view their own tenant" ON tenants;

DROP POLICY IF EXISTS "Super admins can access all tenants" ON tenants;
CREATE POLICY "Super admins can access all tenants"
ON tenants FOR ALL
USING (is_super_admin())
WITH CHECK (is_super_admin());

DROP POLICY IF EXISTS "Members can view their own tenant" ON tenants;
CREATE POLICY "Members can view their own tenant"
ON tenants FOR SELECT
USING (id = current_tenant_context());

DROP POLICY IF EXISTS "Business admins can update their own tenant" ON tenants;
CREATE POLICY "Business admins can update their own tenant"
ON tenants FOR UPDATE
USING (
    id = current_tenant_context()
    AND (SELECT role FROM users WHERE id = auth.uid()) IN ('business_admin', 'super_admin')
)
WITH CHECK (id = current_tenant_context());

-- 5c. demo_requests: anonymous visitors may insert only - Requirement 8.1
DROP POLICY IF EXISTS "Anyone can submit demo requests" ON demo_requests;
DROP POLICY IF EXISTS "Anon can insert demo requests" ON demo_requests;
CREATE POLICY "Anon can insert demo requests"
ON demo_requests FOR INSERT
TO anon, authenticated
WITH CHECK (true);

DROP POLICY IF EXISTS "Super admins can view all demo requests" ON demo_requests;
CREATE POLICY "Super admins can view all demo requests"
ON demo_requests FOR SELECT
TO authenticated
USING (is_super_admin());

DROP POLICY IF EXISTS "Super admins can update demo requests" ON demo_requests;
CREATE POLICY "Super admins can update demo requests"
ON demo_requests FOR UPDATE
TO authenticated
USING (is_super_admin())
WITH CHECK (is_super_admin());

-- 5d. pricing_plans: world readable, super admin writable - Requirement 8.3
DROP POLICY IF EXISTS "Pricing plans are world readable" ON pricing_plans;
CREATE POLICY "Pricing plans are world readable"
ON pricing_plans FOR SELECT
TO anon, authenticated
USING (true);

DROP POLICY IF EXISTS "Super admins manage pricing plans" ON pricing_plans;
CREATE POLICY "Super admins manage pricing plans"
ON pricing_plans FOR ALL
TO authenticated
USING (is_super_admin())
WITH CHECK (is_super_admin());

-- =====================================================
-- 6. GRANTS
-- =====================================================
GRANT ALL ON pharmacists TO authenticated;
GRANT ALL ON pricing_plans TO authenticated;
GRANT ALL ON demo_requests TO authenticated;

-- Anonymous visitors may submit leads and read pricing, nothing else.
GRANT INSERT ON demo_requests TO anon;
REVOKE SELECT, UPDATE, DELETE ON demo_requests FROM anon;
GRANT SELECT ON pricing_plans TO anon;

-- =====================================================
-- 7. UPDATED_AT TRIGGERS
-- =====================================================
DO $$
DECLARE
    t TEXT;
BEGIN
    FOR t IN
        SELECT c.table_name
        FROM information_schema.columns c
        JOIN information_schema.tables tb
          ON tb.table_schema = c.table_schema
         AND tb.table_name = c.table_name
        WHERE c.column_name = 'updated_at'
          AND c.table_schema = 'public'
          AND tb.table_type = 'BASE TABLE'
    LOOP
        EXECUTE format('
            DROP TRIGGER IF EXISTS %1$I ON %2$I;
            CREATE TRIGGER %1$I
            BEFORE UPDATE ON %2$I
            FOR EACH ROW
            EXECUTE FUNCTION update_updated_at_column();
        ', 'update_' || t || '_updated_at', t);
    END LOOP;
END $$;

-- =====================================================
-- 8. INDEXES
-- =====================================================
CREATE INDEX IF NOT EXISTS idx_products_tenant_id ON products(tenant_id);
CREATE INDEX IF NOT EXISTS idx_batches_tenant_branch ON batches(tenant_id, branch_id);
CREATE INDEX IF NOT EXISTS idx_sales_tenant_branch_date ON sales(tenant_id, branch_id, invoice_date DESC);
CREATE INDEX IF NOT EXISTS idx_sale_items_sale_id ON sale_items(sale_id);
CREATE INDEX IF NOT EXISTS idx_sale_items_tenant_id ON sale_items(tenant_id);
CREATE INDEX IF NOT EXISTS idx_customers_tenant_type ON customers(tenant_id, customer_type);
CREATE INDEX IF NOT EXISTS idx_suppliers_tenant_active ON suppliers(tenant_id, is_active);
CREATE INDEX IF NOT EXISTS idx_branches_tenant_active ON branches(tenant_id, is_active);
CREATE INDEX IF NOT EXISTS idx_pharmacists_tenant_active ON pharmacists(tenant_id, is_active);
CREATE INDEX IF NOT EXISTS idx_pharmacists_tenant_name ON pharmacists(tenant_id, name);
CREATE INDEX IF NOT EXISTS idx_pricing_plans_active_order ON pricing_plans(is_active, display_order);
CREATE INDEX IF NOT EXISTS idx_demo_requests_created_at ON demo_requests(created_at DESC);

-- Near-expiry tracking - Requirement 6.1
CREATE INDEX IF NOT EXISTS idx_batches_expiry_date ON batches(exp_date) WHERE stock_quantity > 0;
CREATE INDEX IF NOT EXISTS idx_batches_tenant_expiry ON batches(tenant_id, exp_date) WHERE stock_quantity > 0;

CREATE INDEX IF NOT EXISTS idx_restricted_logs_tenant_date ON restricted_drug_logs(tenant_id, authorization_timestamp DESC);
CREATE INDEX IF NOT EXISTS idx_stock_movements_tenant_product ON stock_movements(tenant_id, product_id, created_at DESC);

-- =====================================================
-- 9. VIEWS
-- =====================================================
-- Dropped and recreated so column list changes do not break re-runs.

DROP VIEW IF EXISTS near_expiry_stock CASCADE;
CREATE VIEW near_expiry_stock AS
SELECT
    b.id AS batch_id,
    b.tenant_id,
    b.branch_id,
    br.branch_name,
    b.product_id,
    p.name AS product_name,
    p.generic_salt,
    p.manufacturer,
    b.batch_number,
    b.exp_date,
    b.stock_quantity,
    b.mrp,
    b.ptr_price,
    b.selling_price,
    b.rack_location,
    -- date - date yields an integer in PostgreSQL, so cast directly.
    -- EXTRACT(DAY FROM ...) over that difference is a type error.
    (b.exp_date - CURRENT_DATE)::INTEGER AS days_until_expiry,
    s.supplier_name,
    CASE
        WHEN b.exp_date < CURRENT_DATE THEN 'expired'
        WHEN (b.exp_date - CURRENT_DATE) <= 30 THEN 'critical'
        WHEN (b.exp_date - CURRENT_DATE) <= 60 THEN 'warning'
        WHEN (b.exp_date - CURRENT_DATE) <= 90 THEN 'near_expiry'
        ELSE 'ok'
    END AS expiry_status
FROM batches b
JOIN products p ON b.product_id = p.id
JOIN branches br ON b.branch_id = br.id
LEFT JOIN suppliers s ON b.supplier_id = s.id
WHERE b.stock_quantity > 0
  -- Widened to a year so the client can apply a configurable window.
  AND b.exp_date <= CURRENT_DATE + INTERVAL '365 days';

DROP VIEW IF EXISTS tenant_dashboard_metrics CASCADE;
CREATE VIEW tenant_dashboard_metrics AS
SELECT
    t.id AS tenant_id,
    t.business_name,
    COUNT(DISTINCT b.id) AS total_branches,
    COUNT(DISTINCT p.id) AS total_products,
    COALESCE(SUM(CASE WHEN bat.stock_quantity > 0 THEN bat.stock_quantity ELSE 0 END), 0) AS total_stock,
    COUNT(DISTINCT c.id) AS total_customers,
    COUNT(DISTINCT s.id) AS total_sales,
    COALESCE(SUM(s.grand_total), 0) AS total_revenue,
    COUNT(DISTINCT CASE WHEN s.invoice_date >= CURRENT_DATE - INTERVAL '30 days' THEN s.id END) AS sales_last_30_days,
    COALESCE(SUM(CASE WHEN s.invoice_date >= CURRENT_DATE - INTERVAL '30 days' THEN s.grand_total ELSE 0 END), 0) AS revenue_last_30_days
FROM tenants t
LEFT JOIN branches b ON t.id = b.tenant_id AND b.is_active = true
LEFT JOIN products p ON t.id = p.tenant_id
LEFT JOIN batches bat ON p.id = bat.product_id
LEFT JOIN customers c ON t.id = c.tenant_id
LEFT JOIN sales s ON t.id = s.tenant_id
WHERE t.is_active = true
GROUP BY t.id, t.business_name;

-- Views default to running with the owner's rights, which would bypass RLS.
-- security_invoker makes the caller's policies apply (PostgreSQL 15+).
DO $$
BEGIN
    EXECUTE 'ALTER VIEW near_expiry_stock SET (security_invoker = true)';
    EXECUTE 'ALTER VIEW tenant_dashboard_metrics SET (security_invoker = true)';
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'security_invoker unavailable on this PostgreSQL version; views run as owner and MUST be filtered by tenant_id in the client';
END $$;

GRANT SELECT ON near_expiry_stock TO authenticated;
GRANT SELECT ON tenant_dashboard_metrics TO authenticated;

-- =====================================================
-- 10. COMMENTS
-- =====================================================
COMMENT ON TABLE pricing_plans IS 'Flexible pricing plans for SaaS subscriptions (world readable)';
COMMENT ON TABLE demo_requests IS 'Demo request leads; insert-only for anonymous visitors';
COMMENT ON TABLE pharmacists IS 'Tenant-scoped pharmacists with salted PIN hashes for Schedule H authorisation';
COMMENT ON COLUMN pharmacists.pin_hash IS 'SHA-256 hash of PIN + pin_salt; plaintext PINs are never stored';
COMMENT ON VIEW near_expiry_stock IS 'Stock expiring within 365 days with days_until_expiry for client-side windowing';
COMMENT ON VIEW tenant_dashboard_metrics IS 'Pre-calculated metrics for tenant dashboards';
COMMENT ON FUNCTION set_tenant_context(UUID) IS 'Sets the session tenant override used by RLS policies';
COMMENT ON FUNCTION current_tenant_context() IS 'Resolves the caller tenant from session override or the users table';
COMMENT ON FUNCTION tenant_access_allowed(UUID) IS 'RLS predicate: true for super admins or the caller own tenant';
COMMENT ON FUNCTION update_updated_at_column() IS 'Automatically updates updated_at timestamp on row updates';
-- =====================================================================
-- END 007_enhance_multi_tenant_features.sql
-- =====================================================================


-- =====================================================================
-- BEGIN 008_product_master_completeness.sql
-- =====================================================================
-- =====================================================
-- Product master completeness + pharmacist PIN alignment
-- =====================================================
-- Adds the product master fields the billing UI collects but 001 never stored,
-- so no UI field exists without a column behind it:
--
--   products.is_chronic            chronic / long-term medication flag
--   products.dose_type             app-side DoseType enum name
--   products.packaging_units_per_strip / packaging_strips_per_box
--                                  flexible pack config (10x10, 10x15, 100ml…)
--   products.default_mrp / default_ptr / default_selling_price /
--   products.default_wholesale_price / default_purchase_price
--                                  catalogue-level defaults; per-batch prices in
--                                  `batches` stay authoritative for billing
--
-- Also aligns the pharmacists table with PharmacistModel, which serialises the
-- hash under `pharmacist_pin_hash` while 007 created `pin_hash`.
--
-- Idempotent: all adds are guarded, safe to re-run.
-- =====================================================

-- ── 1. Product master fields ─────────────────────────────────────────────────
DO $$
DECLARE
    col RECORD;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables
                   WHERE table_schema = 'public' AND table_name = 'products') THEN
        RAISE NOTICE '[008] products table absent; run 001 first';
        RETURN;
    END IF;

    FOR col IN
        SELECT * FROM (VALUES
            ('is_chronic',                 'BOOLEAN DEFAULT false'),
            ('dose_type',                  'VARCHAR(30) DEFAULT ''tablet'''),
            ('packaging_units_per_strip',  'INTEGER'),
            ('packaging_strips_per_box',   'INTEGER DEFAULT 1'),
            ('packaging_label',            'VARCHAR(50)'),
            ('default_purchase_price',     'DECIMAL(15, 2)'),
            ('default_ptr',                'DECIMAL(15, 2)'),
            ('default_mrp',                'DECIMAL(15, 2)'),
            ('default_selling_price',      'DECIMAL(15, 2)'),
            ('default_wholesale_price',    'DECIMAL(15, 2)')
        ) AS v(name, definition)
    LOOP
        IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                       WHERE table_schema = 'public'
                         AND table_name = 'products'
                         AND column_name = col.name) THEN
            EXECUTE format('ALTER TABLE products ADD COLUMN %I %s',
                           col.name, col.definition);
            RAISE NOTICE '[008] products.% added', col.name;
        END IF;
    END LOOP;
END $$;

-- 001 constrains dosage_form to a fixed list that omits 'patch' and
-- 'suppository', both of which DoseType offers. Widen it so the app cannot write
-- a value the constraint rejects.
DO $$
DECLARE
    con_name TEXT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema = 'public' AND table_name = 'products'
                     AND column_name = 'dosage_form') THEN
        RETURN;
    END IF;

    SELECT conname INTO con_name
    FROM pg_constraint
    WHERE conrelid = 'public.products'::regclass
      AND contype = 'c'
      AND pg_get_constraintdef(oid) ILIKE '%dosage_form%'
    LIMIT 1;

    IF con_name IS NOT NULL THEN
        EXECUTE format('ALTER TABLE products DROP CONSTRAINT %I', con_name);
    END IF;

    ALTER TABLE products ADD CONSTRAINT products_dosage_form_check
        CHECK (dosage_form IS NULL OR dosage_form IN (
            'tablet', 'capsule', 'syrup', 'injection', 'cream', 'ointment',
            'drops', 'gel', 'powder', 'lotion', 'suspension', 'inhaler',
            'spray', 'patch', 'suppository', 'other'
        ));
    RAISE NOTICE '[008] products.dosage_form constraint widened';
END $$;

-- packaging_type likewise needs 'blister' and 'unit' for flexible pack configs.
DO $$
DECLARE
    con_name TEXT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema = 'public' AND table_name = 'products'
                     AND column_name = 'packaging_type') THEN
        RETURN;
    END IF;

    SELECT conname INTO con_name
    FROM pg_constraint
    WHERE conrelid = 'public.products'::regclass
      AND contype = 'c'
      AND pg_get_constraintdef(oid) ILIKE '%packaging_type%'
    LIMIT 1;

    IF con_name IS NOT NULL THEN
        EXECUTE format('ALTER TABLE products DROP CONSTRAINT %I', con_name);
    END IF;

    ALTER TABLE products ADD CONSTRAINT products_packaging_type_check
        CHECK (packaging_type IS NULL OR packaging_type IN (
            'strip', 'blister', 'bottle', 'vial', 'box', 'tube', 'sachet',
            'ampoule', 'pen', 'jar', 'unit', 'other'
        ));
    RAISE NOTICE '[008] products.packaging_type constraint widened';
END $$;

-- ── 2. Pharmacist PIN column alignment ───────────────────────────────────────
-- PharmacistModel.toJson writes `pharmacist_pin_hash`; 007 created `pin_hash`.
-- Add the model's column name and keep both in step, so neither the Dart model
-- nor any existing SQL breaks.
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables
                   WHERE table_schema = 'public' AND table_name = 'pharmacists') THEN
        RAISE NOTICE '[008] pharmacists table absent; run 007 first';
        RETURN;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema = 'public' AND table_name = 'pharmacists'
                     AND column_name = 'pharmacist_pin_hash') THEN
        ALTER TABLE pharmacists ADD COLUMN pharmacist_pin_hash VARCHAR(255);
        UPDATE pharmacists SET pharmacist_pin_hash = pin_hash
        WHERE pin_hash IS NOT NULL AND pharmacist_pin_hash IS NULL;
        RAISE NOTICE '[008] pharmacists.pharmacist_pin_hash added and seeded';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema = 'public' AND table_name = 'pharmacists'
                     AND column_name = 'role') THEN
        ALTER TABLE pharmacists ADD COLUMN role VARCHAR(30) DEFAULT 'pharmacist';
    END IF;
END $$;

-- Keep pin_hash and pharmacist_pin_hash consistent regardless of which name the
-- writer used, so PIN verification cannot read a stale hash.
CREATE OR REPLACE FUNCTION sync_pharmacist_pin_hash()
RETURNS TRIGGER AS $$
BEGIN
    IF NEW.pharmacist_pin_hash IS DISTINCT FROM OLD.pharmacist_pin_hash
       AND NEW.pharmacist_pin_hash IS NOT NULL THEN
        NEW.pin_hash := NEW.pharmacist_pin_hash;
    ELSIF NEW.pin_hash IS DISTINCT FROM OLD.pin_hash
       AND NEW.pin_hash IS NOT NULL THEN
        NEW.pharmacist_pin_hash := NEW.pin_hash;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables
               WHERE table_schema = 'public' AND table_name = 'pharmacists') THEN
        DROP TRIGGER IF EXISTS trg_sync_pharmacist_pin_hash ON pharmacists;
CREATE TRIGGER trg_sync_pharmacist_pin_hash
    BEFORE INSERT OR UPDATE ON pharmacists
        FOR EACH ROW EXECUTE FUNCTION sync_pharmacist_pin_hash();
    END IF;
END $$;

-- ── 3. Indexes for the new lookup paths ──────────────────────────────────────
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_schema = 'public' AND table_name = 'products'
                 AND column_name = 'is_chronic') THEN
        CREATE INDEX IF NOT EXISTS idx_products_tenant_chronic
            ON products(tenant_id, is_chronic) WHERE is_chronic = true;
    END IF;

    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_schema = 'public' AND table_name = 'products'
                 AND column_name = 'barcode') THEN
        -- Barcode scanning looks up by tenant + barcode on every scan.
        CREATE INDEX IF NOT EXISTS idx_products_tenant_barcode
            ON products(tenant_id, barcode) WHERE barcode IS NOT NULL;
    END IF;
END $$;

COMMENT ON COLUMN products.is_chronic IS 'Chronic / long-term medication flag';
COMMENT ON COLUMN products.default_ptr IS 'Catalogue default PTR; per-batch ptr_price is authoritative for billing';
-- =====================================================================
-- END 008_product_master_completeness.sql
-- =====================================================================


-- =====================================================================
-- BEGIN 009_backfill_legacy_rows.sql
-- =====================================================================
-- =====================================================
-- Backfill rows parked by migration 000 into the canonical tables
-- =====================================================
-- Runs after 001-008 have created tenants / sales / sale_items.
--
-- WRITTEN AGAINST THE REAL LIVE DATA, inspected with the service-role key:
--
--   companies : 0 rows
--   invoices  : 7 rows, and critically
--                 * "id" is TEXT like 'inv_1790366744736', NOT a uuid
--                 * "companyId" is NULL on every single row
--                 * "items" is a JSON blob; some are '[]'
--                 * "pharmacistPinApprovedBy" holds 'Pharmacist PIN #1234',
--                   i.e. the literal PIN was written into the audit field
--
-- Two consequences drive the design below:
--
-- 1. sales.id is UUID. Inserting the text id directly raises
--    "invalid input syntax for type uuid". A deterministic UUID is derived from
--    the legacy id instead (md5 of the text, shaped into a v4-looking uuid), so
--    re-running maps the same legacy row to the same sales.id and the insert
--    stays idempotent. The original text is kept in sales.legacy_source_id.
--
-- 2. sales.tenant_id is NOT NULL, and every legacy invoice has companyId NULL.
--    There is no correct tenant to assign. Inventing one would attribute real
--    dispensing records to a business that did not make them, which is worse
--    than not migrating them. Those rows therefore stay in invoices_legacy_v0,
--    fully intact, and this migration reports the count loudly so the decision
--    is visible rather than silent.
--
--    If those invoices are later identified as belonging to a specific tenant,
--    set SET app.legacy_target_tenant = '<tenant uuid>' before running and they
--    will be attached to it.
-- =====================================================

-- Derives a stable UUID from arbitrary legacy text.
CREATE OR REPLACE FUNCTION pg_temp.legacy_uuid(p_text TEXT)
RETURNS UUID AS $$
DECLARE
    h TEXT;
BEGIN
    -- NULL in, NULL out: callers use the result in COALESCE and IS NOT NULL
    -- tests, so a NULL companyId must not become a bogus uuid.
    IF p_text IS NULL OR btrim(p_text) = '' THEN
        RETURN NULL;
    END IF;

    -- Already a uuid? Use it unchanged so genuine uuid ids keep their identity.
    IF p_text ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN p_text::uuid;
    END IF;

    h := md5(p_text);
    RETURN (
        substr(h, 1, 8)  || '-' ||
        substr(h, 9, 4)  || '-' ||
        '4' || substr(h, 14, 3) || '-' ||   -- version nibble
        '8' || substr(h, 18, 3) || '-' ||   -- variant nibble
        substr(h, 21, 12)
    )::uuid;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

-- Traceability column so a migrated sale can be tied back to its legacy row.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables
               WHERE table_schema='public' AND table_name='sales')
       AND NOT EXISTS (SELECT 1 FROM information_schema.columns
                       WHERE table_schema='public' AND table_name='sales'
                         AND column_name='legacy_source_id') THEN
        ALTER TABLE sales ADD COLUMN legacy_source_id TEXT;
        COMMENT ON COLUMN sales.legacy_source_id IS
            'Original id from the prototype invoices table, for traceability';
    END IF;

    IF EXISTS (SELECT 1 FROM information_schema.tables
               WHERE table_schema='public' AND table_name='sales')
       AND NOT EXISTS (SELECT 1 FROM information_schema.columns
                       WHERE table_schema='public' AND table_name='sales'
                         AND column_name='legacy_pharmacist_authorized_by') THEN
        -- sales.pharmacist_authorized_by is a UUID FK to users(id); the legacy
        -- value is free text that resolves to no user row.
        ALTER TABLE sales ADD COLUMN legacy_pharmacist_authorized_by TEXT;
        COMMENT ON COLUMN sales.legacy_pharmacist_authorized_by IS
            'Free-text approver label carried over from the prototype invoices table';
    END IF;
END $$;

-- =====================================================
-- 1. companies_legacy_v0 -> tenants
-- =====================================================
DO $$
DECLARE
    moved INTEGER := 0;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables
                   WHERE table_schema = 'public'
                     AND table_name = 'companies_legacy_v0') THEN
        RAISE NOTICE '[009] no companies_legacy_v0, nothing to backfill';
        RETURN;
    END IF;

    INSERT INTO tenants (
        id, business_name, owner_name, email, phone, gstin,
        drug_license_no, address, city, state, pincode,
        industry_type, business_mode, subscription_plan, subscription_status,
        max_branches, is_active, created_at, updated_at
    )
    SELECT
        pg_temp.legacy_uuid(c."id"::text),
        COALESCE(NULLIF(c."businessName", ''), 'Unnamed (migrated)'),
        COALESCE(NULLIF(c."ownerName", ''), 'Unknown'),
        -- tenants.email is UNIQUE in some revisions; keep it deterministic.
        COALESCE(NULLIF(c."email", ''),
                 'migrated+' || left(md5(c."id"::text), 8) || '@invalid.local'),
        COALESCE(NULLIF(c."phone", ''), ''),
        COALESCE(NULLIF(c."gstin", ''), ''),
        COALESCE(NULLIF(c."drugLicenseNo", ''), ''),
        COALESCE(NULLIF(c."address", ''), ''),
        'MIGRATED - SET CITY',
        'MIGRATED - SET STATE',
        '000000',
        CASE lower(COALESCE(c."industryType", ''))
            WHEN 'pharma'    THEN 'pharmacy'
            WHEN 'pharmacy'  THEN 'pharmacy'
            WHEN 'wholesale' THEN 'wholesale'
            WHEN 'retail'    THEN 'retail'
            WHEN 'fmcg'      THEN 'fmcg'
            ELSE 'pharmacy'
        END,
        'retail',
        'Basic',
        'active',
        1,
        COALESCE(c."isActive", true),
        COALESCE(c."createdAt", CURRENT_TIMESTAMP),
        CURRENT_TIMESTAMP
    FROM companies_legacy_v0 c
    WHERE NOT EXISTS (
        SELECT 1 FROM tenants t
        WHERE t.id = pg_temp.legacy_uuid(c."id"::text)
    );

    GET DIAGNOSTICS moved = ROW_COUNT;
    RAISE NOTICE '[009] backfilled % tenant(s) from companies_legacy_v0', moved;
END $$;

-- =====================================================
-- 2. invoices_legacy_v0 -> sales
-- =====================================================
DO $$
DECLARE
    moved         INTEGER := 0;
    unattributed  INTEGER := 0;
    total_legacy  INTEGER := 0;
    target_tenant UUID;
    rec           RECORD;
    new_uid       UUID;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables
                   WHERE table_schema = 'public'
                     AND table_name = 'invoices_legacy_v0') THEN
        RAISE NOTICE '[009] no invoices_legacy_v0, nothing to backfill';
        RETURN;
    END IF;

    SELECT COUNT(*) INTO total_legacy FROM invoices_legacy_v0;

    -- Optional operator override for invoices that carry no companyId.
    BEGIN
        target_tenant := NULLIF(current_setting('app.legacy_target_tenant', true), '')::uuid;
    EXCEPTION WHEN OTHERS THEN
        target_tenant := NULL;
    END;

    IF target_tenant IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM tenants WHERE id = target_tenant) THEN
        RAISE WARNING '[009] app.legacy_target_tenant % is not an existing tenant; ignoring',
            target_tenant;
        target_tenant := NULL;
    END IF;

    -- Count rows that cannot be attributed to any tenant.
    SELECT COUNT(*) INTO unattributed
    FROM invoices_legacy_v0 i
    WHERE target_tenant IS NULL
      AND (i."companyId" IS NULL
           OR NOT EXISTS (
               SELECT 1 FROM tenants t
               WHERE t.id = pg_temp.legacy_uuid(i."companyId"::text)));

    -- Every migrated tenant needs a system author, because sales.created_by is
    -- NOT NULL and the legacy rows recorded no user.
    -- legacy_uuid() must do the conversion; a direct ::uuid cast on the raw
    -- legacy text ('comp_1790300000000') raises "invalid input syntax for uuid".
    FOR rec IN
        SELECT DISTINCT
            COALESCE(target_tenant,
                     pg_temp.legacy_uuid(i."companyId"::text)) AS tenant_id
        FROM invoices_legacy_v0 i
        WHERE target_tenant IS NOT NULL
           OR NULLIF(i."companyId"::text, '') IS NOT NULL
    LOOP
        CONTINUE WHEN rec.tenant_id IS NULL;
        CONTINUE WHEN NOT EXISTS (SELECT 1 FROM tenants WHERE id = rec.tenant_id);
        CONTINUE WHEN EXISTS (
            SELECT 1 FROM users u
            WHERE u.tenant_id = rec.tenant_id
              AND u.email = 'migration@system.local');

        new_uid := uuid_generate_v4();
        BEGIN
            INSERT INTO auth.users (id, email)
            VALUES (new_uid, 'migration@system.local')
            ON CONFLICT (id) DO NOTHING;
        EXCEPTION WHEN insufficient_privilege OR undefined_table OR unique_violation THEN
            NULL;  -- managed auth schema, or the address already exists
        END;

        BEGIN
            INSERT INTO users (id, tenant_id, name, email, role, is_active)
            VALUES (new_uid, rec.tenant_id, 'Legacy Data Migration',
                    'migration@system.local', 'business_admin', false);
        EXCEPTION WHEN foreign_key_violation OR unique_violation THEN
            RAISE NOTICE '[009] no system user for tenant %; its legacy sales are skipped',
                rec.tenant_id;
        END;
    END LOOP;

    -- A branch is required (sales.branch_id NOT NULL) and the legacy rows had none.
    INSERT INTO branches (
        id, tenant_id, branch_name, branch_code, address, city, state, pincode,
        drug_license_no, phone, email, manager_name, is_active
    )
    SELECT
        uuid_generate_v4(), t.id, 'Migrated Records', 'MIGRATED',
        '', 'MIGRATED - SET CITY', 'MIGRATED - SET STATE', '000000',
        '', '', '', '', true
    FROM tenants t
    WHERE EXISTS (
        SELECT 1 FROM invoices_legacy_v0 i
        WHERE COALESCE(target_tenant, pg_temp.legacy_uuid(i."companyId"::text)) = t.id
    )
    AND NOT EXISTS (
        SELECT 1 FROM branches b
        WHERE b.tenant_id = t.id AND b.branch_code = 'MIGRATED'
    );

    INSERT INTO sales (
        id, legacy_source_id, tenant_id, branch_id, invoice_number, invoice_date,
        customer_name, customer_phone, doctor_name, doctor_mci_no,
        subtotal, item_discount_total, invoice_discount, taxable_amount,
        cgst_amount, sgst_amount, igst_amount, total_gst, round_off,
        grand_total, payment_mode, payment_status,
        legacy_pharmacist_authorized_by, is_synced, billing_type,
        created_by, created_at, updated_at
    )
    SELECT
        pg_temp.legacy_uuid(i."id"::text),
        i."id"::text,
        COALESCE(target_tenant, pg_temp.legacy_uuid(i."companyId"::text)),
        (SELECT b.id FROM branches b
          WHERE b.tenant_id = COALESCE(target_tenant,
                                       pg_temp.legacy_uuid(i."companyId"::text))
            AND b.branch_code = 'MIGRATED'
          LIMIT 1),
        COALESCE(NULLIF(i."invoiceNumber", ''),
                 'MIGRATED-' || left(md5(i."id"::text), 8)),
        COALESCE(i."timestamp", CURRENT_TIMESTAMP),
        COALESCE(NULLIF(i."customerName", ''), 'Walk-in Customer'),
        COALESCE(NULLIF(i."customerPhone", ''), ''),
        i."doctorName",
        i."doctorMciNo",
        -- Line items were a JSON blob with no computed totals. Sum what is
        -- recoverable; leave the GST split at zero rather than inventing a tax
        -- breakdown that was never recorded.
        COALESCE(src.gross, 0),
        0,
        COALESCE(i."discountAmount", 0),
        0, 0, 0, 0, 0, 0,
        GREATEST(COALESCE(src.gross, 0) - COALESCE(i."discountAmount", 0), 0),
        CASE lower(COALESCE(i."paymentMode", 'cash'))
            WHEN 'card'   THEN 'card'
            WHEN 'upi'    THEN 'upi'
            WHEN 'credit' THEN 'credit'
            WHEN 'split'  THEN 'split'
            ELSE 'cash'
        END,
        'paid',
        i."pharmacistPinApprovedBy",
        COALESCE(i."isSynced", true),
        'retail',
        (SELECT u.id FROM users u
          WHERE u.tenant_id = COALESCE(target_tenant,
                                       pg_temp.legacy_uuid(i."companyId"::text))
            AND u.email = 'migration@system.local'
          LIMIT 1),
        COALESCE(i."timestamp", CURRENT_TIMESTAMP),
        CURRENT_TIMESTAMP
    FROM invoices_legacy_v0 i
    CROSS JOIN LATERAL (
        SELECT COALESCE(SUM(
                   COALESCE((it->>'quantity')::numeric, 0)
                 * COALESCE((it->>'unitPrice')::numeric, 0)), 0) AS gross
        FROM jsonb_array_elements(
            CASE
                WHEN i."items" IS NULL THEN '[]'::jsonb
                WHEN jsonb_typeof(
                        CASE WHEN pg_typeof(i."items")::text = 'jsonb'
                             THEN i."items"::jsonb
                             ELSE i."items"::text::jsonb END) = 'array'
                    THEN CASE WHEN pg_typeof(i."items")::text = 'jsonb'
                              THEN i."items"::jsonb
                              ELSE i."items"::text::jsonb END
                ELSE '[]'::jsonb
            END) AS it
    ) src
    WHERE COALESCE(target_tenant, pg_temp.legacy_uuid(i."companyId"::text)) IS NOT NULL
      AND EXISTS (
          SELECT 1 FROM tenants t
          WHERE t.id = COALESCE(target_tenant,
                                pg_temp.legacy_uuid(i."companyId"::text)))
      AND EXISTS (
          SELECT 1 FROM users u
          WHERE u.tenant_id = COALESCE(target_tenant,
                                       pg_temp.legacy_uuid(i."companyId"::text))
            AND u.email = 'migration@system.local')
      AND NOT EXISTS (
          SELECT 1 FROM sales s
          WHERE s.id = pg_temp.legacy_uuid(i."id"::text));

    GET DIAGNOSTICS moved = ROW_COUNT;

    RAISE NOTICE '[009] invoices_legacy_v0: % total, % migrated to sales, % left unattributed',
        total_legacy, moved, unattributed;

    IF unattributed > 0 THEN
        RAISE WARNING '[009] % legacy invoice(s) have no companyId and were NOT migrated. They remain intact in invoices_legacy_v0. To attach them to a tenant, run: SET app.legacy_target_tenant = ''<tenant-uuid>''; then re-apply this migration.',
            unattributed;
    END IF;

    -- sale_items is deliberately not backfilled: the legacy JSON embeds whole
    -- product/batch objects whose prototype ids do not resolve to rows in
    -- products/batches, and sale_items.product_id is a FK. Fabricating catalogue
    -- rows to satisfy it would corrupt the product master. The JSON stays
    -- readable in invoices_legacy_v0 for anyone who needs the detail.
END $$;

DO $$
BEGIN
    RAISE NOTICE '[009] legacy backfill complete. All *_legacy_v0 rows are retained.';
END $$;
-- =====================================================================
-- END 009_backfill_legacy_rows.sql
-- =====================================================================


-- =====================================================================
-- BEGIN 010_fix_schedule_h_audit.sql
-- =====================================================================
-- =====================================================
-- Fix Schedule H audit logging (blocking production bug)
-- =====================================================
-- FOUND BY EXECUTION, not inspection:
--
-- 1. `sales.pharmacist_authorized_by` is UUID REFERENCES users(id), but the app
--    writes a human label there ('Dr Rao (PIN verified)'). That is a type error
--    on every authorised sale.
--
-- 2. The 004 trigger log_restricted_drug_sale() copies that value into
--    `restricted_drug_logs.pharmacist_id`, which is NOT NULL. When the value is
--    NULL the INSERT aborts, and because the trigger fires AFTER INSERT ON
--    sale_items the whole sale is rolled back. Net effect: selling ANY
--    Schedule H / H1 / narcotic product is impossible.
--
-- FIX
--   * add sales.authorized_pharmacist_id -> pharmacists(id), the real authoriser
--   * add sales.pharmacist_authorized_name TEXT for the display label
--   * make restricted_drug_logs.pharmacist_id nullable and add
--     pharmacist_ref + pharmacist_name so the audit trail records identity even
--     when the authoriser is a pharmacists row rather than a users row
--   * rewrite the trigger to resolve identity from either source and never abort
--     a legitimate sale
--
-- Compliance note: the log still refuses to record a restricted sale with no
-- authorising identity at all. It raises a clear exception in that case instead
-- of silently writing an unattributed Schedule H record.
-- =====================================================

-- ── 1. Sales columns ─────────────────────────────────────────────────────────
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema='public' AND table_name='sales'
                     AND column_name='authorized_pharmacist_id') THEN
        ALTER TABLE sales ADD COLUMN authorized_pharmacist_id UUID
            REFERENCES pharmacists(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema='public' AND table_name='sales'
                     AND column_name='pharmacist_authorized_name') THEN
        ALTER TABLE sales ADD COLUMN pharmacist_authorized_name TEXT;
    END IF;
END $$;

-- ── 2. Audit log columns ─────────────────────────────────────────────────────
DO $$
BEGIN
    -- Relax NOT NULL so a pharmacists-table authoriser does not abort the sale.
    IF EXISTS (SELECT 1 FROM information_schema.columns
               WHERE table_schema='public' AND table_name='restricted_drug_logs'
                 AND column_name='pharmacist_id' AND is_nullable='NO') THEN
        ALTER TABLE restricted_drug_logs ALTER COLUMN pharmacist_id DROP NOT NULL;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema='public' AND table_name='restricted_drug_logs'
                     AND column_name='pharmacist_ref') THEN
        ALTER TABLE restricted_drug_logs ADD COLUMN pharmacist_ref UUID
            REFERENCES pharmacists(id) ON DELETE SET NULL;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema='public' AND table_name='restricted_drug_logs'
                     AND column_name='pharmacist_name') THEN
        ALTER TABLE restricted_drug_logs ADD COLUMN pharmacist_name TEXT;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema='public' AND table_name='restricted_drug_logs'
                     AND column_name='branch_id') THEN
        ALTER TABLE restricted_drug_logs ADD COLUMN branch_id UUID
            REFERENCES branches(id) ON DELETE SET NULL;
    END IF;
END $$;

-- ── 3. Rewrite the trigger ───────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION log_restricted_drug_sale()
RETURNS TRIGGER AS $$
DECLARE
    v_is_restricted BOOLEAN;
    v_product_name  VARCHAR(500);
    v_sale          RECORD;
    v_ph_name       TEXT;
BEGIN
    SELECT (is_schedule_h OR is_schedule_h1 OR is_narcotic), name
      INTO v_is_restricted, v_product_name
      FROM products WHERE id = NEW.product_id;

    IF NOT COALESCE(v_is_restricted, false) THEN
        RETURN NEW;
    END IF;

    SELECT * INTO v_sale FROM sales WHERE id = NEW.sale_id;

    -- Resolve the authoriser's display name from whichever source is populated.
    v_ph_name := COALESCE(
        v_sale.pharmacist_authorized_name,
        (SELECT p.name FROM pharmacists p WHERE p.id = v_sale.authorized_pharmacist_id),
        (SELECT u.name FROM users u WHERE u.id = v_sale.pharmacist_authorized_by)
    );

    -- A restricted sale with no authorising identity is a compliance failure.
    -- Fail loudly rather than writing an unattributable Schedule H record.
    IF v_sale.authorized_pharmacist_id IS NULL
       AND v_sale.pharmacist_authorized_by IS NULL
       AND v_ph_name IS NULL THEN
        RAISE EXCEPTION
            'Schedule H/H1/narcotic item "%" requires pharmacist authorisation on sale %',
            v_product_name, NEW.sale_id
            USING HINT = 'Set authorized_pharmacist_id (or pharmacist_authorized_by) before inserting sale items';
    END IF;

    INSERT INTO restricted_drug_logs (
        tenant_id, branch_id, sale_id, product_id, product_name, batch_number,
        quantity, customer_name, doctor_name, doctor_mci_no,
        pharmacist_id, pharmacist_ref, pharmacist_name, prescription_id
    )
    VALUES (
        v_sale.tenant_id, v_sale.branch_id, NEW.sale_id, NEW.product_id,
        v_product_name, NEW.batch_number, NEW.quantity, v_sale.customer_name,
        v_sale.doctor_name, v_sale.doctor_mci_no,
        v_sale.pharmacist_authorized_by,
        v_sale.authorized_pharmacist_id,
        v_ph_name,
        v_sale.prescription_id
    );

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_log_restricted_drug_sale ON sale_items;
CREATE TRIGGER trigger_log_restricted_drug_sale
    AFTER INSERT ON sale_items
    FOR EACH ROW EXECUTE FUNCTION log_restricted_drug_sale();

-- ── 4. Guard the money invariant in the database ─────────────────────────────
-- The Dart layer clamps the discount, but a stale client or a direct API call
-- must not be able to persist a negative payable.
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conrelid='public.sales'::regclass
                     AND conname='sales_grand_total_non_negative') THEN
        ALTER TABLE sales ADD CONSTRAINT sales_grand_total_non_negative
            CHECK (grand_total >= 0);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conrelid='public.sales'::regclass
                     AND conname='sales_invoice_discount_non_negative') THEN
        ALTER TABLE sales ADD CONSTRAINT sales_invoice_discount_non_negative
            CHECK (invoice_discount >= 0);
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conrelid='public.batches'::regclass
                     AND conname='batches_stock_non_negative') THEN
        -- Overselling a batch into negative stock is always a bug.
        ALTER TABLE batches ADD CONSTRAINT batches_stock_non_negative
            CHECK (stock_quantity >= 0);
    END IF;
END $$;

COMMENT ON COLUMN sales.authorized_pharmacist_id IS
    'Pharmacist who authorised a Schedule H/H1/narcotic sale (pharmacists.id)';
COMMENT ON COLUMN sales.pharmacist_authorized_name IS
    'Display name of the authorising pharmacist, captured at sale time';
COMMENT ON COLUMN restricted_drug_logs.pharmacist_name IS
    'Authoriser identity for the Schedule H register; never stores a PIN';

-- =====================================================
-- 5. Fix stock deduction to include free quantity
-- =====================================================
-- FOUND BY EXECUTION: update_stock_on_sale() in 004 deducts only NEW.quantity.
-- Free goods are physically handed to the customer, so a scheme sale of
-- "10 + 2 free" removed 10 units while 12 left the shelf. Inventory drifted
-- upward by the free amount on every scheme sale, and the stock_movements
-- ledger recorded the wrong figure too.
--
-- Deduct quantity + free_quantity, and record both parts in the movement notes
-- so the ledger explains the number.
CREATE OR REPLACE FUNCTION update_stock_on_sale()
RETURNS TRIGGER AS $$
DECLARE
    v_total      INTEGER := NEW.quantity + COALESCE(NEW.free_quantity, 0);
    v_remaining  INTEGER;
BEGIN
    UPDATE batches
    SET stock_quantity = stock_quantity - v_total
    WHERE id = NEW.batch_id
    RETURNING stock_quantity INTO v_remaining;

    IF v_remaining IS NULL THEN
        RAISE EXCEPTION 'Batch % not found for sale item', NEW.batch_id;
    END IF;

    IF v_remaining < 0 THEN
        RAISE EXCEPTION
            'Insufficient stock for batch %: need % (incl. % free), short by %',
            NEW.batch_id, v_total, COALESCE(NEW.free_quantity, 0), abs(v_remaining);
    END IF;

    INSERT INTO stock_movements (
        tenant_id, product_id, batch_id, branch_id, movement_type,
        quantity, reference_id, notes, created_by
    )
    SELECT
        s.tenant_id, NEW.product_id, NEW.batch_id, s.branch_id, 'sale',
        -v_total, NEW.sale_id,
        'Sale invoice: ' || s.invoice_number ||
          CASE WHEN COALESCE(NEW.free_quantity, 0) > 0
               THEN format(' (%s billed + %s free)', NEW.quantity, NEW.free_quantity)
               ELSE '' END,
        s.created_by
    FROM sales s
    WHERE s.id = NEW.sale_id;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_update_stock_on_sale ON sale_items;
CREATE TRIGGER trigger_update_stock_on_sale
    AFTER INSERT ON sale_items
    FOR EACH ROW EXECUTE FUNCTION update_stock_on_sale();

COMMENT ON FUNCTION update_stock_on_sale() IS
    'Deducts billed + free quantity from batch stock and records the movement';
-- =====================================================================
-- END 010_fix_schedule_h_audit.sql
-- =====================================================================


-- =====================================================================
-- BEGIN 011_customer_refill_requests.sql
-- =====================================================================
-- =====================================================
-- Customer chronic refill requests
-- =====================================================
-- The customer portal offers a "request refill" action for chronic medicines.
-- Previously that button only called notifyListeners(), so nothing was ever
-- recorded and no member of staff could act on it. This gives the request a
-- real home, tenant-scoped like every other business table.
--
-- Idempotent: safe to re-run.
-- =====================================================

CREATE TABLE IF NOT EXISTS customer_refill_requests (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    customer_id UUID NOT NULL REFERENCES customers(id) ON DELETE CASCADE,
    medicine_name VARCHAR(500) NOT NULL,
    quantity INTEGER,
    notes TEXT,
    status VARCHAR(30) NOT NULL DEFAULT 'requested'
        CHECK (status IN ('requested', 'contacted', 'fulfilled', 'cancelled')),
    requested_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    fulfilled_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Guarded column adds for databases where an earlier version exists.
DO $$
DECLARE
    col RECORD;
BEGIN
    FOR col IN
        SELECT * FROM (VALUES
            ('quantity',     'INTEGER'),
            ('notes',        'TEXT'),
            ('requested_at', 'TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP'),
            ('fulfilled_at', 'TIMESTAMP WITH TIME ZONE'),
            ('updated_at',   'TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP')
        ) AS v(name, definition)
    LOOP
        IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                       WHERE table_schema = 'public'
                         AND table_name = 'customer_refill_requests'
                         AND column_name = col.name) THEN
            EXECUTE format('ALTER TABLE customer_refill_requests ADD COLUMN %I %s',
                           col.name, col.definition);
        END IF;
    END LOOP;
END $$;

ALTER TABLE customer_refill_requests ENABLE ROW LEVEL SECURITY;

-- Same single-predicate tenant gate used by every other business table.
DROP POLICY IF EXISTS "Tenant isolation on customer_refill_requests"
    ON customer_refill_requests;
CREATE POLICY "Tenant isolation on customer_refill_requests"
ON customer_refill_requests FOR ALL
USING (tenant_access_allowed(tenant_id))
WITH CHECK (tenant_access_allowed(tenant_id));

GRANT ALL ON customer_refill_requests TO authenticated;

CREATE INDEX IF NOT EXISTS idx_refill_requests_tenant_status
    ON customer_refill_requests(tenant_id, status, requested_at DESC);
CREATE INDEX IF NOT EXISTS idx_refill_requests_customer
    ON customer_refill_requests(customer_id, requested_at DESC);

DROP TRIGGER IF EXISTS set_updated_at_customer_refill_requests
    ON customer_refill_requests;
CREATE TRIGGER set_updated_at_customer_refill_requests
    BEFORE UPDATE ON customer_refill_requests
    FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

COMMENT ON TABLE customer_refill_requests IS
    'Chronic medicine refill requests raised from the customer portal';
-- =====================================================================
-- END 011_customer_refill_requests.sql
-- =====================================================================


-- =====================================================================
-- BEGIN 012_subscription_plans_payments.sql
-- =====================================================================
-- =====================================================
-- BillSprout/LifeSprout - Subscription Plans & Payment Tables
-- =====================================================
-- This migration creates tables for subscription management and payment processing
-- Created: 2024
-- Description: Subscription plans, pricing tiers, payment transactions, and webhooks

-- =====================================================
-- 1. SUBSCRIPTION PLANS TABLE
-- =====================================================
CREATE TABLE IF NOT EXISTS subscription_plans (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    plan_name VARCHAR(100) NOT NULL UNIQUE,
    plan_code VARCHAR(50) NOT NULL UNIQUE,
    description TEXT,
    price_monthly DECIMAL(10,2) NOT NULL,
    price_yearly DECIMAL(10,2) NOT NULL,
    price_currency VARCHAR(3) DEFAULT 'INR',
    max_branches INTEGER NOT NULL DEFAULT 1,
    max_users INTEGER NOT NULL DEFAULT 5,
    max_products INTEGER NOT NULL DEFAULT 1000,
    max_invoices_per_month INTEGER NOT NULL DEFAULT 500,
    features JSONB, -- JSON array of feature names
    is_active BOOLEAN DEFAULT true,
    display_order INTEGER DEFAULT 0,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- =====================================================
-- 2. TENANT SUBSCRIPTIONS TABLE
-- =====================================================
CREATE TABLE IF NOT EXISTS tenant_subscriptions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    plan_id UUID NOT NULL REFERENCES subscription_plans(id) ON DELETE RESTRICT,
    billing_cycle VARCHAR(20) NOT NULL CHECK (billing_cycle IN ('monthly', 'yearly', 'trial')),
    status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'expired', 'cancelled', 'suspended')),
    amount_paid DECIMAL(10,2),
    payment_method VARCHAR(50),
    start_date TIMESTAMP WITH TIME ZONE NOT NULL,
    end_date TIMESTAMP WITH TIME ZONE NOT NULL,
    auto_renew BOOLEAN DEFAULT true,
    razorpay_subscription_id VARCHAR(255),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Index for tenant subscription lookups
CREATE INDEX idx_tenant_subscriptions_tenant ON tenant_subscriptions(tenant_id);
CREATE INDEX idx_tenant_subscriptions_status ON tenant_subscriptions(status);

-- =====================================================
-- 3. PAYMENT TRANSACTIONS TABLE
-- =====================================================
CREATE TABLE IF NOT EXISTS payment_transactions (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
    subscription_id UUID REFERENCES tenant_subscriptions(id) ON DELETE SET NULL,
    amount DECIMAL(10,2) NOT NULL,
    currency VARCHAR(3) DEFAULT 'INR',
    status VARCHAR(20) NOT NULL CHECK (status IN ('pending', 'processing', 'success', 'failed', 'refunded')),
    payment_method VARCHAR(50),
    payment_gateway VARCHAR(50) DEFAULT 'razorpay',
    
    -- Razorpay specific fields
    razorpay_order_id VARCHAR(255),
    razorpay_payment_id VARCHAR(255),
    razorpay_signature VARCHAR(500),
    
    -- Transaction metadata
    transaction_type VARCHAR(50) CHECK (transaction_type IN ('subscription', 'renewal', 'upgrade', 'refund')),
    description TEXT,
    metadata JSONB,
    
    -- Timestamps
    payment_initiated_at TIMESTAMP WITH TIME ZONE,
    payment_completed_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Indexes for payment lookups
CREATE INDEX idx_payment_transactions_tenant ON payment_transactions(tenant_id);
CREATE INDEX idx_payment_transactions_status ON payment_transactions(status);
CREATE INDEX idx_payment_transactions_razorpay_order ON payment_transactions(razorpay_order_id);
CREATE INDEX idx_payment_transactions_razorpay_payment ON payment_transactions(razorpay_payment_id);

-- =====================================================
-- 4. WEBHOOK LOGS TABLE (for payment webhooks)
-- =====================================================
CREATE TABLE IF NOT EXISTS webhook_logs (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    source VARCHAR(50) NOT NULL, -- 'razorpay', 'other_gateway'
    event_type VARCHAR(100) NOT NULL, -- e.g., 'payment.captured', 'subscription.cancelled'
    payload JSONB NOT NULL,
    signature VARCHAR(500),
    status VARCHAR(20) NOT NULL CHECK (status IN ('received', 'processing', 'processed', 'failed')),
    error_message TEXT,
    processed_at TIMESTAMP WITH TIME ZONE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Index for webhook debugging
CREATE INDEX idx_webhook_logs_event_type ON webhook_logs(event_type);
CREATE INDEX idx_webhook_logs_status ON webhook_logs(status);
CREATE INDEX idx_webhook_logs_created_at ON webhook_logs(created_at DESC);

-- =====================================================
-- 5. INSERT DEFAULT SUBSCRIPTION PLANS
-- =====================================================

INSERT INTO subscription_plans (plan_name, plan_code, description, price_monthly, price_yearly, max_branches, max_users, max_products, max_invoices_per_month, features, display_order) VALUES
(
    'Basic',
    'basic',
    'Perfect for small pharmacies and retail stores',
    499.00,
    4999.00,
    1,
    3,
    500,
    200,
    '["Single Branch", "Up to 3 Users", "500 Products", "200 Invoices/Month", "Basic Reports", "Email Support", "Mobile App Access"]'::jsonb,
    1
),
(
    'Professional',
    'professional',
    'Ideal for growing businesses with multiple locations',
    1499.00,
    14999.00,
    5,
    10,
    5000,
    1000,
    '["Up to 5 Branches", "Up to 10 Users", "5000 Products", "1000 Invoices/Month", "Advanced Reports", "Priority Email Support", "Mobile App Access", "API Access", "Custom Branding", "Multi-Branch Management"]'::jsonb,
    2
),
(
    'Enterprise',
    'enterprise',
    'For large organizations requiring unlimited scale',
    4999.00,
    49999.00,
    999,
    999,
    999999,
    999999,
    '["Unlimited Branches", "Unlimited Users", "Unlimited Products", "Unlimited Invoices", "Advanced Analytics & BI", "24/7 Phone Support", "Mobile App Access", "API Access", "Custom Branding", "Multi-Branch Management", "Dedicated Account Manager", "Custom Integrations", "SLA Guarantee"]'::jsonb,
    3
);

-- =====================================================
-- 6. RLS POLICIES FOR SUBSCRIPTION TABLES
-- =====================================================

-- Enable RLS
ALTER TABLE subscription_plans ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenant_subscriptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE payment_transactions ENABLE ROW LEVEL SECURITY;
ALTER TABLE webhook_logs ENABLE ROW LEVEL SECURITY;

-- Subscription Plans: Public read (for plan selection page)
CREATE POLICY "Subscription plans are viewable by everyone"
    ON subscription_plans FOR SELECT
    USING (is_active = true);

-- Super admin can manage plans
CREATE POLICY "Super admins can manage subscription plans"
    ON subscription_plans FOR ALL
    USING (
        EXISTS (
            SELECT 1 FROM users
            WHERE users.id = auth.uid()
            AND users.role = 'super_admin'
        )
    );

-- Tenant Subscriptions: Tenant can view their own
CREATE POLICY "Tenants can view their own subscriptions"
    ON tenant_subscriptions FOR SELECT
    USING (tenant_id = get_current_tenant_id());

-- Super admin can view all subscriptions
CREATE POLICY "Super admins can view all subscriptions"
    ON tenant_subscriptions FOR SELECT
    USING (is_super_admin());

-- Super admin and system can insert subscriptions
CREATE POLICY "Super admins can manage subscriptions"
    ON tenant_subscriptions FOR ALL
    USING (is_super_admin());

-- Payment Transactions: Tenant can view their own
CREATE POLICY "Tenants can view their own payment transactions"
    ON payment_transactions FOR SELECT
    USING (tenant_id = get_current_tenant_id());

-- Tenant can insert payment transactions (for initiating payments)
CREATE POLICY "Tenants can create payment transactions"
    ON payment_transactions FOR INSERT
    WITH CHECK (tenant_id = get_current_tenant_id());

-- Super admin can view all transactions
CREATE POLICY "Super admins can view all payment transactions"
    ON payment_transactions FOR SELECT
    USING (is_super_admin());

-- Webhook Logs: Only super admin access
CREATE POLICY "Super admins can view webhook logs"
    ON webhook_logs FOR SELECT
    USING (is_super_admin());

CREATE POLICY "System can insert webhook logs"
    ON webhook_logs FOR INSERT
    WITH CHECK (true); -- Service role key will handle this

-- =====================================================
-- 7. FUNCTIONS & TRIGGERS
-- =====================================================

-- Function to update tenant subscription status
CREATE OR REPLACE FUNCTION update_tenant_subscription_status()
RETURNS TRIGGER AS $$
BEGIN
    -- Update tenant's subscription_plan and subscription_status
    UPDATE tenants
    SET 
        subscription_plan = (SELECT plan_code FROM subscription_plans WHERE id = NEW.plan_id),
        subscription_status = NEW.status,
        updated_at = CURRENT_TIMESTAMP
    WHERE id = NEW.tenant_id;
    
    RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Trigger to sync tenant subscription changes
CREATE TRIGGER sync_tenant_subscription_status
AFTER INSERT OR UPDATE ON tenant_subscriptions
FOR EACH ROW
EXECUTE FUNCTION update_tenant_subscription_status();

-- Function to check subscription validity
CREATE OR REPLACE FUNCTION is_subscription_active(tenant_uuid UUID)
RETURNS BOOLEAN AS $$
DECLARE
    subscription_active BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM tenant_subscriptions
        WHERE tenant_id = tenant_uuid
        AND status = 'active'
        AND end_date > CURRENT_TIMESTAMP
    ) INTO subscription_active;
    
    RETURN subscription_active;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- =====================================================
-- 8. UPDATE TIMESTAMPS TRIGGER
-- =====================================================

CREATE OR REPLACE FUNCTION update_subscription_timestamp()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER update_subscription_plans_timestamp
BEFORE UPDATE ON subscription_plans
FOR EACH ROW
EXECUTE FUNCTION update_subscription_timestamp();

CREATE TRIGGER update_tenant_subscriptions_timestamp
BEFORE UPDATE ON tenant_subscriptions
FOR EACH ROW
EXECUTE FUNCTION update_subscription_timestamp();

CREATE TRIGGER update_payment_transactions_timestamp
BEFORE UPDATE ON payment_transactions
FOR EACH ROW
EXECUTE FUNCTION update_subscription_timestamp();

-- =====================================================
-- END OF MIGRATION
-- =====================================================
-- =====================================================================
-- END 012_subscription_plans_payments.sql
